-- ─── 2. Point the district rows at their polygons ───────────────────────────────────────
-- Compton: the geo_ids already exist; only the layer code was missing.
UPDATE essentials.districts d
   SET mtfcc = 'X0001'
 WHERE d.id IN ('4be5abff-3c1a-4f69-8973-9d3b492b6740','8db1a555-4df8-49f8-9e8c-8c44c4d175d0',
                '12b18632-99fd-4bfb-834e-31060a9ec5c5','09038ab4-538e-48c8-8150-62b9271fec10')
   AND d.geo_id LIKE 'compton-council-district-%'
   AND d.mtfcc IS DISTINCT FROM 'X0001';

-- Pomona: move each council district off the whole-city polygon.
UPDATE essentials.districts d
   SET geo_id = v.geo_id, mtfcc = 'X0001'
  FROM (VALUES
    ('e282b5d3-b1dc-4966-ad72-9f0629660f79'::uuid, 'pomona-council-district-1'),
    ('3a213f0d-bcbd-4243-b576-b9c18c621520'::uuid, 'pomona-council-district-2'),
    ('35d17606-34ce-47cd-ad83-abde1821cabe'::uuid, 'pomona-council-district-3'),
    ('7adbe57d-515a-4848-9320-ccbf3feeeeb2'::uuid, 'pomona-council-district-4'),
    ('c821d0fb-e0a5-492f-a8a4-7a4b00c362d5'::uuid, 'pomona-council-district-5'),
    ('1946c2e2-a863-45fd-a2d7-56f20c7201ae'::uuid, 'pomona-council-district-6')
  ) AS v(id, geo_id)
 WHERE d.id = v.id AND d.geo_id = '0658072' AND d.district_type = 'LOCAL';

-- ─── 3. Races (reuse the seated offices; primary_party NULL) ────────────────────────────
INSERT INTO essentials.races (election_id, office_id, position_name, primary_party, seats)
SELECT 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid, v.office_id, v.position_name, NULL, 1
  FROM (VALUES
    ('Compton Mayor',                   '4c7e41d1-5789-450a-bfe7-0da2291b9ac5'::uuid),
    ('Compton City Council District 2', 'e0ed6496-f17d-46be-a8d0-48c1e43d685d'::uuid),
    ('Pomona City Council District 2',  'b6ac307c-2152-4117-a9a3-77ef282c5e03'::uuid)
  ) AS v(position_name, office_id)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.races r
                    WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.position_name);

-- ─── 4. Candidates (the two advancing per seat) ─────────────────────────────────────────
INSERT INTO essentials.race_candidates
       (race_id, politician_id, full_name, first_name, last_name, is_incumbent, candidate_status, source)
SELECT r.id, v.politician_id, v.full_name, v.first_name, v.last_name, v.is_incumbent, 'active',
       'LA County Registrar-Recorder, June 2 2026 Statewide Direct Primary final canvass (results.lavote.gov/text-results/4338, as of 06/26/2026): top two advancing to the Nov 3 2026 runoff. Retrieved 2026-09-22.'
  FROM (VALUES
    ('Compton Mayor', 'Emma Sharif',    'Emma',    'Sharif',   '174f3f47-e4ee-4775-ab6f-f1039d608098'::uuid, true),
    ('Compton Mayor', 'Andre Spicer',   'Andre',   'Spicer',   'f63d8129-c569-4ea5-bd77-5cda877b2185'::uuid, false),
    ('Compton City Council District 2', 'Bennie Tinson',  'Bennie',  'Tinson',  NULL::uuid, false),
    ('Compton City Council District 2', 'Anthony Perry',  'Anthony', 'Perry',   NULL::uuid, false),
    ('Pomona City Council District 2',  'Victor Preciado','Victor',  'Preciado','56cecf7c-6de0-440f-b8e2-34945ec52333'::uuid, true),
    ('Pomona City Council District 2',  'Jacky Elizalde', 'Jacky',   'Elizalde', NULL::uuid, false)
  ) AS v(position_name, full_name, first_name, last_name, politician_id, is_incumbent)
  JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.position_name
 WHERE NOT EXISTS (SELECT 1 FROM essentials.race_candidates rc
                    WHERE rc.race_id = r.id AND lower(rc.full_name) = lower(v.full_name));

-- ─── 5. Post-verify gate ────────────────────────────────────────────────────────────────
DO $$
DECLARE
  n_gf int; n_bad_dist int; n_races int; n_cands int; n_party int; n_null_office int;
  n_overlap int; n_wrong int; n_race_wrong int; n_invalid int;
  co_cov double precision; py_cov double precision;
BEGIN
  SELECT count(*) INTO n_gf FROM essentials.geofence_boundaries
   WHERE mtfcc = 'X0001' AND (geo_id LIKE 'compton-council-district-%' OR geo_id LIKE 'pomona-council-district-%');
  IF n_gf <> 10 THEN RAISE EXCEPTION 'expected 10 council polygons, got %', n_gf; END IF;

  SELECT count(*) INTO n_invalid FROM essentials.geofence_boundaries
   WHERE mtfcc = 'X0001' AND (geo_id LIKE 'compton-council-district-%' OR geo_id LIKE 'pomona-council-district-%')
     AND NOT public.ST_IsValid(geometry);
  IF n_invalid <> 0 THEN RAISE EXCEPTION '% invalid council polygon(s)', n_invalid; END IF;

  -- every Compton/Pomona council district row now points at a polygon that exists
  SELECT count(*) INTO n_bad_dist FROM essentials.districts d
   WHERE d.id IN ('4be5abff-3c1a-4f69-8973-9d3b492b6740','8db1a555-4df8-49f8-9e8c-8c44c4d175d0',
                  '12b18632-99fd-4bfb-834e-31060a9ec5c5','09038ab4-538e-48c8-8150-62b9271fec10',
                  'e282b5d3-b1dc-4966-ad72-9f0629660f79','3a213f0d-bcbd-4243-b576-b9c18c621520',
                  '35d17606-34ce-47cd-ad83-abde1821cabe','7adbe57d-515a-4848-9320-ccbf3feeeeb2',
                  'c821d0fb-e0a5-492f-a8a4-7a4b00c362d5','1946c2e2-a863-45fd-a2d7-56f20c7201ae')
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries b WHERE b.geo_id = d.geo_id AND b.mtfcc = d.mtfcc);
  IF n_bad_dist <> 0 THEN RAISE EXCEPTION '% council district row(s) do not resolve to a polygon', n_bad_dist; END IF;

  -- coverage vs the TIGER place polygon, with tolerance (two digitisations never match exactly).
  -- Planar SRID-4326 area: the check is a RATIO over one small city, so degrees are fine, and a
  -- ::geography cast is banned here (it reads public.spatial_ref_sys -- ev-cto decision 0006).
  SELECT abs(public.ST_Area(c.geometry) - public.ST_Area(u.g)) / public.ST_Area(c.geometry)
    INTO co_cov
    FROM essentials.geofence_boundaries c,
         (SELECT public.ST_Union(geometry) g FROM essentials.geofence_boundaries
           WHERE mtfcc = 'X0001' AND geo_id LIKE 'compton-council-district-%') u
   WHERE c.geo_id = '0615044' AND c.mtfcc = 'G4110';
  SELECT abs(public.ST_Area(c.geometry) - public.ST_Area(u.g)) / public.ST_Area(c.geometry)
    INTO py_cov
    FROM essentials.geofence_boundaries c,
         (SELECT public.ST_Union(geometry) g FROM essentials.geofence_boundaries
           WHERE mtfcc = 'X0001' AND geo_id LIKE 'pomona-council-district-%') u
   WHERE c.geo_id = '0658072' AND c.mtfcc = 'G4110';
  IF co_cov > 0.03 OR py_cov > 0.03 THEN
    RAISE EXCEPTION 'district union differs from the city polygon: Compton % pct, Pomona % pct',
      round((co_cov*100)::numeric,2), round((py_cov*100)::numeric,2);
  END IF;

  -- districts partition each city (no overlap beyond a sliver)
  SELECT count(*) INTO n_overlap
    FROM essentials.geofence_boundaries a JOIN essentials.geofence_boundaries b
      ON a.geo_id < b.geo_id AND a.mtfcc = 'X0001' AND b.mtfcc = 'X0001'
     AND ((a.geo_id LIKE 'compton-council-district-%' AND b.geo_id LIKE 'compton-council-district-%')
       OR (a.geo_id LIKE 'pomona-council-district-%'  AND b.geo_id LIKE 'pomona-council-district-%'))
   WHERE public.ST_Area(public.ST_Intersection(a.geometry, b.geometry)) > 1e-7;  -- ~1,000 m2 at 34 N
  IF n_overlap <> 0 THEN RAISE EXCEPTION '% council district pair(s) overlap by more than ~1000 m2', n_overlap; END IF;

  -- END TO END: an interior point of each district returns exactly that district's member
  SELECT count(*) INTO n_wrong
    FROM (VALUES ('compton-council-district-1','Deidre Duhart'), ('compton-council-district-2','Andre Spicer'),
                 ('compton-council-district-3','Jonathan Bowers'), ('compton-council-district-4','Lillie P. Darden'),
                 ('pomona-council-district-1','Debra Martin'), ('pomona-council-district-2','Victor Preciado'),
                 ('pomona-council-district-3','Nora Garcia'), ('pomona-council-district-4','Elizabeth Ontiveros-Cole'),
                 ('pomona-council-district-5','Steve Lustro'), ('pomona-council-district-6','Lorraine Canales')) AS want(g, who)
    JOIN essentials.geofence_boundaries b ON b.geo_id = want.g AND b.mtfcc = 'X0001'
    LEFT JOIN LATERAL (
      SELECT string_agg(p.full_name, ', ' ORDER BY p.full_name) AS got
        FROM essentials.geofence_boundaries gb
        JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'LOCAL'
        JOIN essentials.offices o ON o.district_id = d.id
        JOIN essentials.office_current_holder och ON och.office_id = o.id
        JOIN essentials.politicians p ON p.id = och.politician_id
       WHERE gb.mtfcc = 'X0001' AND (gb.geo_id LIKE 'compton-council-district-%' OR gb.geo_id LIKE 'pomona-council-district-%')
         AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(b.geometry))
    ) hit ON true
   WHERE hit.got IS DISTINCT FROM want.who;
  IF n_wrong <> 0 THEN RAISE EXCEPTION '% council district(s) do not return exactly their own member', n_wrong; END IF;

  -- races + candidates
  SELECT count(*) INTO n_races FROM essentials.races
   WHERE election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid
     AND position_name IN ('Compton Mayor','Compton City Council District 2','Pomona City Council District 2');
  SELECT count(*) INTO n_cands FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid
     AND r.position_name IN ('Compton Mayor','Compton City Council District 2','Pomona City Council District 2');
  SELECT count(*) INTO n_party FROM essentials.races
   WHERE election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND primary_party IS NOT NULL
     AND position_name IN ('Compton Mayor','Compton City Council District 2','Pomona City Council District 2');
  SELECT count(*) INTO n_null_office FROM essentials.races
   WHERE election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND office_id IS NULL
     AND position_name IN ('Compton Mayor','Compton City Council District 2','Pomona City Council District 2');
  IF n_races <> 3 THEN RAISE EXCEPTION 'expected 3 runoff races, got %', n_races; END IF;
  IF n_cands <> 6 THEN RAISE EXCEPTION 'expected 6 runoff candidates, got %', n_cands; END IF;
  IF n_party <> 0 OR n_null_office <> 0 THEN RAISE EXCEPTION 'party (%) or office-less (%) race', n_party, n_null_office; END IF;

  -- each DISTRICT race is reached only inside its own district: a point in the NEIGHBOURING
  -- district of the same city must not see it
  SELECT count(*) INTO n_race_wrong
    FROM (VALUES ('Compton City Council District 2','compton-council-district-2',true),
                 ('Compton City Council District 2','compton-council-district-3',false),
                 ('Pomona City Council District 2','pomona-council-district-2',true),
                 ('Pomona City Council District 2','pomona-council-district-5',false)) AS t(pos, g, should)
    JOIN essentials.geofence_boundaries pt ON pt.geo_id = t.g AND pt.mtfcc = 'X0001'
   WHERE t.should IS DISTINCT FROM EXISTS (
     SELECT 1 FROM essentials.races r
       JOIN essentials.offices o ON o.id = r.office_id
       JOIN essentials.districts d ON d.id = o.district_id
       JOIN essentials.geofence_boundaries gb ON gb.geo_id = d.geo_id AND (d.mtfcc IS NULL OR gb.mtfcc = d.mtfcc)
      WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = t.pos
        AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(pt.geometry)));
  IF n_race_wrong <> 0 THEN RAISE EXCEPTION '% district race reach check(s) failed', n_race_wrong; END IF;

  RAISE NOTICE 'CA_0141 applied: 10 council polygons, % races, % candidates', n_races, n_cands;
END $$;

COMMIT;
